-- Install only after migration 0109 and schema/retention review.
-- These triggers enforce closure tombstones even when the web feature is disabled.
CREATE TRIGGER IF NOT EXISTS "portability_giving_funds_insert" BEFORE INSERT ON "giving_funds" WHEN EXISTS(SELECT 1 FROM parish_data_closures c WHERE (1=1) AND ((NEW.parish_id = c.parish_id))) BEGIN SELECT RAISE(ABORT,'PARISH_CLOSURE_WRITE_BLOCKED'); END;
