CREATE TRIGGER IF NOT EXISTS "portability_app_settings_insert" BEFORE INSERT ON "app_settings" WHEN EXISTS(SELECT 1 FROM parish_data_closures c WHERE (1=1) AND (((NEW.key = 'parish-feature-requests:' || c.parish_id OR substr(NEW.key,1,length('reconciliation-close:' || c.parish_id || ':')) = 'reconciliation-close:' || c.parish_id || ':' OR (substr(NEW.key,1,15)<>'__agapay_learn_' AND CASE WHEN json_valid(NEW.value) THEN COALESCE(json_extract(NEW.value,'$.parishId'),json_extract(NEW.value,'$.parish_id'),json_extract(NEW.value,'$.organizationId')) END = c.parish_id))))) BEGIN SELECT RAISE(ABORT,'PARISH_CLOSURE_WRITE_BLOCKED'); END;
CREATE TRIGGER IF NOT EXISTS "portability_app_settings_update" BEFORE UPDATE ON "app_settings" WHEN EXISTS(SELECT 1 FROM parish_data_closures c WHERE (1=1) AND (((OLD.key = 'parish-feature-requests:' || c.parish_id OR substr(OLD.key,1,length('reconciliation-close:' || c.parish_id || ':')) = 'reconciliation-close:' || c.parish_id || ':' OR (substr(OLD.key,1,15)<>'__agapay_learn_' AND CASE WHEN json_valid(OLD.value) THEN COALESCE(json_extract(OLD.value,'$.parishId'),json_extract(OLD.value,'$.parish_id'),json_extract(OLD.value,'$.organizationId')) END = c.parish_id))) OR ((NEW.key = 'parish-feature-requests:' || c.parish_id OR substr(NEW.key,1,length('reconciliation-close:' || c.parish_id || ':')) = 'reconciliation-close:' || c.parish_id || ':' OR (substr(NEW.key,1,15)<>'__agapay_learn_' AND CASE WHEN json_valid(NEW.value) THEN COALESCE(json_extract(NEW.value,'$.parishId'),json_extract(NEW.value,'$.parish_id'),json_extract(NEW.value,'$.organizationId')) END = c.parish_id))))) BEGIN SELECT RAISE(ABORT,'PARISH_CLOSURE_WRITE_BLOCKED'); END;
CREATE TRIGGER IF NOT EXISTS "portability_app_settings_delete" BEFORE DELETE ON "app_settings" WHEN EXISTS(SELECT 1 FROM parish_data_closures c WHERE (c.state IN ('preparing','closed')) AND (((OLD.key = 'parish-feature-requests:' || c.parish_id OR substr(OLD.key,1,length('reconciliation-close:' || c.parish_id || ':')) = 'reconciliation-close:' || c.parish_id || ':' OR (substr(OLD.key,1,15)<>'__agapay_learn_' AND CASE WHEN json_valid(OLD.value) THEN COALESCE(json_extract(OLD.value,'$.parishId'),json_extract(OLD.value,'$.parish_id'),json_extract(OLD.value,'$.organizationId')) END = c.parish_id))))) BEGIN SELECT RAISE(ABORT,'PARISH_CLOSURE_WRITE_BLOCKED'); END;
